module bracket(size) {
  // Define the dimensions of the bracket
  size = size / 2;

  // Define the outer dimensions of the bracket
  outer_height = 5 + size * 2;
  outer_width = 5 + size * 2;

  // Define the inner dimensions of the bracket
  inner_height = 5 + size * 2 - 5;
  inner_width = 5 + size * 2 - 5;

  // Define the holes
  hole_center = [0, 0, 5 + size * 2 - 5];

  // Define the hole radius
  hole_radius = 5;

  // Create the bracket
  difference() {
    // Create the outer part of the bracket
    cube([outer_width, outer_height, outer_width]);

    // Create the inner part of the bracket
    difference() {
      cube([inner_width, inner_height, inner_width]);

      // Create the holes
      translate([0, 0, 5]) {
        cylinder(r=hole_radius, h=outer_height - inner_height);
        translate([0, 0, outer_height - hole_radius]) {
          cylinder(r=hole_radius, h=hole_radius);
        }
      }
    }
  }
}

