module bracket(size) {
  // Define the dimensions of the bracket
  length = size * 0.7;
  width = size * 0.5;
  height = size * 0.8;

  // Define the dimensions of the smaller sphere
  sphere_radius = size * 0.2;

  // Create the bracket
  translate([0, 0, height]) {
    cylinder(h=height, r=length/2);
    translate([0, 0, -height]) {
      difference() {
        cylinder(h=height, r=length/2);
        difference() {
          cylinder(h=height, r=sphere_radius);
          translate([0, width/2, 0]) {
            difference() {
              cylinder(h=height, r=sphere_radius);
              translate([0, -width/2, 0]) {
                cylinder(h=height, r=sphere_radius);
              }
            }
          }
        }
      }
    }
  }
}

