module parametric_enclosure_base(size, thickness, bolt_diameter) {
    // Create the base body
    difference() {
        cube([size, size, thickness]);
        // Create bolt holes in the corners
        translate([-(size / 2), -(size / 2), thickness + bolt_diameter / 2]) {
            cylinder(r=bolt_diameter / 2, h=size - bolt_diameter);
        }
        translate([-(size / 2), (size / 2), thickness + bolt_diameter / 2]) {
            cylinder(r=bolt_diameter / 2, h=size - bolt_diameter);
        }
        translate([(size / 2), -(size / 2), thickness + bolt_diameter / 2]) {
            cylinder(r=bolt_diameter / 2, h=size - bolt_diameter);
        }
        translate([(size / 2), (size / 2), thickness + bolt_diameter / 2]) {
            cylinder(r=bolt_diameter / 2, h=size - bolt_diameter);
        }
    }
}

