    // Define the inner cylinder
    cylinder(d=size-2*thickness, h=size-2*thickness, center=true, chamfer=0.5);
    // Define the flange
    difference() {
        cylinder(d=size-2*thickness, h=size, center=true, chamfer=0.5);
        cylinder(d=size-2*thickness, h=size-2*thickness, center=true, chamfer=0.5);
        translate([0, size/2, -thickness/2]) {
            translate([bolt_diameter/2, 0, 0]) cylinder(d=bolt_diameter, h=size, center=true, chamfer=0.5);
            translate([-bolt_diameter/2, 0, 0]) cylinder(d=bolt_diameter, h=size, center=true, chamfer=0.5);
            translate([0, 0, bolt_diameter/2]) cylinder(d=bolt_diameter, h=size, center=true, chamfer=0.5);
            translate([0, 0, -bolt_diameter/2]) cylinder(d=bolt_diameter, h=size, center=true, chamfer=0.5);
        }
    }
