module shaft_collar(size=100, thickness=6, chamfer=2){
    // Create the outer cylinder
    cylinder(h=size-thickness, r=size/2, center=true, chamfer=chamfer);

    // Create the inner cylinder
    cylinder(h=thickness, r=size/2-0.5, center=true, chamfer=chamfer);

    // Create the screw hole
    translate([0, size/2, thickness/2]) cylinder(h=2, r=1.5, center=true, chamfer=chamfer);

    // Create the stem
    translate([0, size/2, size-thickness/2]) cylinder(h=thickness, r=1.5, center=true, chamfer=chamfer);

    // Create the cap
