module spacer_bushing(size, thickness) {
    // Create the main body of the bushing
    difference() {
        translate([0, 0, 0.5 * thickness]) {
            cube([size - 2 * thickness, size - 2 * thickness, thickness], center = true);
        }
        // Create the countersunk recess
        translate([size / 4, size / 4, 0.5 * thickness]) {
            cylinder(r = 4, h = thickness, center = true);
        }
    }
}

