// Spacer bushing with an M4 screw recess
module spacer_bushing(size=78, thickness=13) {
    // Cut the center of the bushing
    union() {
        // Bottom part
        linear_extrude(height=size - thickness, center=true) {
            translate([0, 0, thickness / 2]) {
                difference() {
                    cylinder(r=10, h=size - thickness, center=true, chamfer=0.5);
                    translate([0, 0, thickness / 2]) {
                        difference() {
                            cylinder(r=10, h=size - thickness, center=true, chamfer=0.5);
                        }
                    }
                }
            }
        }
        // Top part
        linear_extrude(height=thickness, center=true) {
            translate([0, 0, 0]) {
                difference() {
                    cylinder(r=10, h=thickness, center=true, chamfer=0.5);
                    translate([0, 0, thickness / 2]) {
                        difference() {
                            cylinder(r=10, h=thickness, center=true, chamfer=0.5);
                        }
                    }
                }
            }
        }
        // Center part
        linear_extrude(height=thickness, center=true) {
            translate([0, 0, 0]) {
                difference() {
                    cylinder(r=10, h=thickness, center=true, chamfer=0.5);
                    translate([0, 0, thickness / 2]) {
                        difference() {
                            cylinder(r=10, h=thickness, center=true, chamfer=0.5);
                        }
                    }
                }
            }
        }
    }
    // M4 screw recess
    translate([0, 0, size / 2]) {
        difference() {
            cylinder(r=2, h=size, center=true, chamfer=0.5);
            translate([0, 0, thickness / 2]) {
                difference() {
                    cylinder(r=2, h=size, center=true, chamfer=0.5);
                }
            }
        }
    }
}

