module heavy_duty_hinge(base_diameter, base_height, cylinder_diameter, cylinder_height) {
    // Base plate
    cylinder(
        radius = base_diameter / 2,
        height = base_height,
        center = [0, base_height / 2, 0],
        material = "steel"
    );

    // Central cylinder
    cylinder(
        radius = cylinder_diameter / 2,
        height = cylinder_height,
        center = [0, cylinder_height / 2, 0],
        material = "aluminum"
    );

    // Union to combine the base plate and central cylinder
    union() {
        cylinder(
            radius = base_diameter / 2,
            height = base_height,
            center = [0, base_height / 2, 0],
            material = "steel"
        );
        cylinder(
            radius = cylinder_diameter / 2,
            height = cylinder_height,
            center = [0, cylinder_height / 2, 0],
            material = "aluminum"
        );
    }
}

