module nema17_bracket(
  diameter = 40,
  thickness = 4,
  hole_size = 5,
  hole_center = [0, 0, 0]
) {
  // Define the bracket body
  difference() {
    translate([0, diameter/2, thickness/2]) {
      cube([diameter, diameter, thickness]);
    }
    translate([0, -diameter/2, thickness/2]) {
      cube([diameter, diameter, thickness]);
    }
    translate([thickness/2, 0, diameter/2]) {
      cube([thickness, diameter, diameter]);
    }
    translate([-thickness/2, 0, diameter/2]) {
      cube([thickness, diameter, diameter]);
    }
    translate([0, 0, thickness/2 - hole_size/2]) {
      difference() {
        cylinder(r = hole_size/2, h = hole_size, center = true);
        translate([0, hole_size/2, 0]) {
          cylinder(r = hole_size/2, h = hole_size, center = true);
        }
      }
    }
  }

  // Draw the through-hole
  translate([hole_center[0], hole_center[1], hole_center[2] - thickness/2]) {
    cylinder(r = hole_size/2, h = thickness, center = true);
  }
}

