module corner_l_bracket(size, thickness) {
    // Define the dimensions of the L-bracket
    L = size - thickness;
    T = thickness;

    // Define the parameters for the countersunk recess
    R = L / 4;
    H = 2 * R;

    // Define the outer cylinder for the L-bracket
    cylinder(r=L, h=L-T, center=true, chamfer=true, $fn=100);

    // Define the inner cylinder for the L-bracket
    cylinder(r=R, h=T, center=true, chamfer=true, $fn=100);

    // Define the countersunk recess
    translate([0, 0, T]) cylinder(r=R, h=H, center=true, chamfer=true, $fn=100);

    // Define the screw hole in the center of the L-bracket
    translate([0, 0, L-T]) cylinder(r=R/2, h=L-T, center=true, chamfer=true, $fn=100);
}

