// Define the flanged bearing housing
module flanged_bearing_housing(radius, thickness, bolt_hole_diameter) {
    // Define the outer cylinder
    cylinder(r=radius, h=thickness+1.5*thickness, center=true, resolution=100, chamfer=2, chamfer_radius=1);

    // Define the inner cylinder
    cylinder(r=radius-1, h=thickness-1.5*thickness, center=true, resolution=100, chamfer=2, chamfer_radius=1);

    // Define the flange
    translate([0, thickness/2, thickness/2]) {
        cylinder(r=radius-1, h=thickness-1, center=true, resolution=100, chamfer=2, chamfer_radius=1);
    }

    // Define the bolt holes
    translate([radius/2, -bolt_hole_diameter/2, thickness/2]) {
        cylinder(r=bolt_hole_diameter/2, h=thickness-1.5*thickness, center=true, resolution=100, chamfer=2, chamfer_radius=1);
    }
    translate([-radius/2, -bolt_hole_diameter/2, thickness/2]) {
        cylinder(r=bolt_hole_diameter/2, h=thickness-1.5*thickness, center=true, resolution=100, chamfer=2, chamfer_radius=1);
    }
    translate([radius/2, bolt_hole_diameter/2, -thickness/2]) {
        cylinder(r=bolt_hole_diameter/2, h=thickness-1.5*thickness, center=true, resolution=100, chamfer=2, chamfer_radius=1);
    }
    translate([-radius/2, bolt_hole_diameter/2, -thickness/2]) {
        cylinder(r=bolt_hole_diameter/2, h=thickness-1.5*thickness, center=true, resolution=100, chamfer=2, chamfer_radius=1);
    }
}

