module shaft_collar(
  diameter = 92mm,
  thickness = 5mm,
  screw_diameter = 4mm,
  screw_length = 12mm
) {
  // Create the shaft collar body
  cylinder(
    radius = diameter / 2,
    height = thickness - screw_length,
    center = true,
    chamfer = 0.5,
    segments = 100
  );

  // Create the screw hole
  cylinder(
    radius = screw_diameter / 2,
    height = screw_length,
    center = true,
    chamfer = 0.5,
    segments = 100
  );

  // Create the countersunk recess for the M4 screw
  translate([0, 0, thickness - screw_length - 0.5]) {
    cylinder(
      radius = screw_diameter / 2,
      height = screw_length + 0.5,
      center = true,
      chamfer = 0.5,
      segments = 100
    );
  }
}

