module LBracket(size, thickness) {
    // L-bracket dimensions
    width = size - 2 * thickness;
    height = 4 * thickness;

    // Chamfer radius
    chamfer_radius = 2;

    // Create the L-bracket
    difference() {
        // Base of the L-bracket
        translate([0, thickness, thickness]) cube([width, height, thickness * 4]);

        // Top face of the L-bracket
        translate([0, height, 0]) rotate([0, 90, 0]) cube([width, thickness, thickness * 4]);

        // Bottom face of the L-bracket
        translate([0, -height, 0]) rotate([0, 90, 180]) cube([width, thickness, thickness * 4]);

        // Front face of the L-bracket
        translate([thickness, 0, 0]) rotate([90, 0, 0]) cube([thickness * 4, height, thickness]);

        // Back face of the L-bracket
        translate([width - thickness, 0, 0]) rotate([-90, 0, 0]) cube([thickness * 4, height, thickness]);
    }

    // Chamfer the outer edges
    translate([0, thickness, 0]) rotate([0, 90, 0]) cube([width, thickness, thickness * 4], chamfer_radius);
    translate([0, height, 0]) rotate([0, 90, 0]) cube([width, thickness, thickness * 4], chamfer_radius);
    translate([0, -height, 0]) rotate([0, 90, 0]) cube([width, thickness, thickness * 4], chamfer_radius);
    translate([thickness, 0, 0]) rotate([90, 0, 0]) cube([thickness * 4, height, thickness], chamfer_radius);
    translate([width - thickness, 0, 0]) rotate([-90, 0, 0]) cube([thickness * 4, height, thickness], chamfer_radius);
}

