module heavyDutyStructuralHinge(size, thickness, chamfer) {
    // Define the hinge body
    hull(size - 2 * chamfer, thickness - 2 * chamfer) {
        // Define the base of the hinge
        linear_extrude(height = 3) {
            polygon(points = [
                [0, 0],
                [size, 0],
                [size, thickness],
                [0, thickness]
            ]);
        }
        // Define the top of the hinge
        linear_extrude(height = 2) {
            polygon(points = [
                [0, 0],
                [size, 0],
                [size, thickness],
                [0, thickness]
            ]);
        }
        // Define the top face of the hinge
        difference() {
            union() {
                translate([0, thickness - 1, 0]) {
                    hull(size - 2 * chamfer, thickness - 2 * chamfer);
                }
                translate([0, 1, 0]) {
                    linear_extrude(height = 2) {
                        polygon(points = [
                            [0, 0],
                            [size, 0],
                            [size, thickness],
                            [0, thickness]
                        ]);
                    }
                }
            }
            translate([0, 0, thickness - 1]) {
                hull(size - 2 * chamfer, thickness - 2 * chamfer);
            }
        }
    }
}

