module corner_l_bracket(
    height = 49,
    width = 21,
    thickness = 14,
    chamfer_radius = 2
) {
    // Create the base
    difference() {
        cube([height, width, thickness]);
        // Add the top corner
        linear_extrude(height - 2 * chamfer_radius) {
            cylinder(r=chamfer_radius, h=thickness);
        }
        // Add the bottom corner
        linear_extrude(height - 2 * chamfer_radius) {
            cylinder(r=chamfer_radius, h=thickness);
        }
    }

    // Add the edges
    linear_extrude(thickness) {
        difference() {
            cube([height, width, thickness - 2 * chamfer_radius]);
            // Add the left edge
            translate([chamfer_radius, 0, 0]) cylinder(r=chamfer_radius, h=height - 2 * chamfer_radius);
            // Add the right edge
            translate([width - chamfer_radius, 0, 0]) cylinder(r=chamfer_radius, h=height - 2 * chamfer_radius);
            // Add the bottom edge
            translate([0, chamfer_radius, 0]) cylinder(r=chamfer_radius, h=width - 2 * chamfer_radius);
            // Add the top edge
            translate([0, width - chamfer_radius, 0]) cylinder(r=chamfer_radius, h=height - 2 * chamfer_radius);
        }
    }
}

