    difference() {
        cube([size, thickness, thickness], center = true);
        cylinder(r = 2, h = thickness, center = true, bottom = false);
        cylinder(r = 2, h = thickness, center = true, top = false);
    }

    // Define the countersunk recess for the M4 screw
    translate([0, thickness, 0]) {
        cylinder(r = 2, h = thickness, center = true);
        translate([0, 0, thickness]) {
            cylinder(r = 2, h = thickness, center = true);
        }
    }

    // Define the screw hole
    translate([size/2 - thickness/2, thickness, size/2 - thickness/2]) {
        cylinder(r = 2, h = thickness/2, center = true, bottom = false);
        cylinder(r = 2, h = thickness/2, center = true, top = false);
    }
}

