module mount_bracket(size, thickness) {
    // Define the overall dimensions of the mount bracket
    m = size;
    h = thickness;

    // Calculate the dimensions of the countersunk recess
    r = h * 0.25;

    // Create the mounting bracket using CSG operations
    difference() {
        // Define the bottom part of the bracket
        translate([0, 0, h]) {
            cylinder(r=3, d=m, h=h, $fn=50);
        }
        // Define the top part of the bracket
        translate([0, 0, 0]) {
            cylinder(r=2, d=m, h=h, $fn=50);
        }
        // Define the bottom recess
        translate([0, 0, h]) {
            cylinder(r=r, d=m, h=r, $fn=50);
        }
    }
}

