module electronics_enclosure_base(size, thickness) {
    // Define the overall dimensions of the enclosure base
    base_width = size - (2 * thickness);
    base_length = size - (2 * thickness);
    base_depth = thickness;

    // Define the outer dimensions of the base
    outer_width = size;
    outer_length = size;
    outer_depth = thickness + 10;

    // Define the inner dimensions of the base
    inner_width = size - 10;
    inner_length = size - 10;
    inner_depth = thickness - 10;

    // Create the base with a difference of a central through-hole
    difference() {
        cube([outer_width, outer_length, outer_depth]);
        cube([inner_width, inner_length, inner_depth]);
        cube([5, 5, 5], center = [0, 0, 5]); // Central through-hole
    }
}

