module flanged_bearing_housing(size, thickness, hole_diameter) {
    // Create the base cylinder
    cylinder(size, thickness);

    // Create the inner cylindrical hole
    difference() {
        cylinder(size - 0.1 * hole_diameter, thickness);
        cylinder(size - 0.1 * hole_diameter, thickness);
    }

    // Create the flange with holes
    translate([0, thickness / 2, -0.5 * hole_diameter / 2]) {
        cylinder(size + hole_diameter, thickness);
    }

    // Create the inner flange with holes
    translate([0, thickness / 2, 0.5 * hole_diameter / 2]) {
        cylinder(size + hole_diameter, thickness);
    }

    // Create the bolt holes in the corners
    translate([-(size - hole_diameter) / 4, -(size - hole_diameter) / 4, -0.5 * hole_diameter / 2]) {
        cylinder(hole_diameter, thickness);
    }

    translate([(size + hole_diameter) / 4, -(size - hole_diameter) / 4, -0.5 * hole_diameter / 2]) {
        cylinder(hole_diameter, thickness);
    }

    translate([-(size - hole_diameter) / 4, (size + hole_diameter) / 4, -0.5 * hole_diameter / 2]) {
        cylinder(hole_diameter, thickness);
    }

    translate([(size + hole_diameter) / 4, (size + hole_diameter) / 4, -0.5 * hole_diameter / 2]) {
        cylinder(hole_diameter, thickness);
    }
}

