// Define the hinge parameters
module heavyDutyStructuralHinge(
    thickness = 6,
    holeDiameter = 3,
    holeSpacing = 22
) {
    // Create the hinge body
    difference() {
        union() {
            // Create the base of the hinge
            translate([0, thickness/2, 0]) {
                cylinder(r=holeDiameter/2, h=88, center=true);
            }

            // Create the top of the hinge
            translate([0, 88, 0]) {
                cylinder(r=holeDiameter/2, h=holeSpacing, center=true);
            }

            // Create the bottom of the hinge
            translate([0, 0, 0]) {
                cylinder(r=holeDiameter/2, h=holeSpacing, center=true);
            }

            // Create the corners of the hinge
            translate([0, 0, 0]) {
                cylinder(r=holeDiameter/2, h=thickness, center=true);
            }

            translate([holeSpacing, 0, 0]) {
                cylinder(r=holeDiameter/2, h=thickness, center=true);
            }

            translate([0, holeSpacing, 0]) {
                cylinder(r=holeDiameter/2, h=thickness, center=true);
            }

            translate([holeSpacing, holeSpacing, 0]) {
                cylinder(r=holeDiameter/2, h=thickness, center=true);
            }
        }
    }

    // Define the bolt holes
    translate([0, thickness/2, 0]) {
        translate([0, holeSpacing/2, 0]) {
            hole(diameter=holeDiameter);
        }

        translate([holeSpacing, holeSpacing/2, 0]) {
            hole(diameter=holeDiameter);
        }

        translate([holeSpacing, 0, holeSpacing/2]) {
            hole(diameter=holeDiameter);
        }

        translate([0, holeSpacing, holeSpacing/2]) {
            hole(diameter=holeDiameter);
        }
    }

    // Define the bolt holes in the top and bottom corners
    translate([0, 88, 0]) {
        translate([0, holeSpacing/2, 0]) {
            hole(diameter=holeDiameter);
        }

        translate([holeSpacing, holeSpacing/2, 0]) {
            hole(diameter=holeDiameter);
        }
    }

    translate([0, 0, 0]) {
        translate([0, holeSpacing/2, 0]) {
            hole(diameter=holeDiameter);
        }

        translate([holeSpacing, holeSpacing/2, 0]) {
            hole(diameter=holeDiameter);
        }
    }
}

