module LBracket(size, thickness, bolt_diameter, bolt_spacing) {
    // Define the L-bracket shape
    LBracketBase(size, thickness);
    LBracketHead(bolt_diameter, bolt_spacing);
}

module LBracketBase(size, thickness) {
    // Create the base of the L-bracket
    union() {
        difference() {
            cube([size[0], size[1], thickness]);
            cylinder(r1=thickness/2, r2=0, h=size[2], center=true);
        }
        translate([size[0]/2, size[1]/2, thickness/2]) {
            cylinder(r1=thickness/2, r2=0, h=size[2], center=true);
        }
    }
}

module LBracketHead(bolt_diameter, bolt_spacing) {
    // Create the head of the L-bracket
    union() {
        translate([-(bolt_diameter/2) + bolt_spacing, -(bolt_diameter/2) + bolt_spacing, thickness/2]) {
            cylinder(r1=thickness/2, r2=0, h=thickness/2, center=true);
        }
        translate([-(bolt_diameter/2) + bolt_spacing, (bolt_diameter/2) - bolt_spacing, thickness/2]) {
            cylinder(r1=thickness/2, r2=0, h=thickness/2, center=true);
        }
        translate([(bolt_diameter/2) - bolt_spacing, -(bolt_diameter/2) + bolt_spacing, thickness/2]) {
            cylinder(r1=thickness/2, r2=0, h=thickness/2, center=true);
        }
        translate([(bolt_diameter/2) - bolt_spacing, (bolt_diameter/2) - bolt_spacing, thickness/2]) {
            cylinder(r1=thickness/2, r2=0, h=thickness/2, center=true);
        }
    }
}

