module flanged_bushing(size, thickness, hex_diameter, hex_height) {
    // Define the flange
    difference() {
        // Create the outer flange
        cylinder(r1=size/2, r2=size/2-thickness, h=size+thickness, center=true, chamfer=thickness/2);

        // Create the hexagonal recess
        hexagon(h=hex_height, r=hex_diameter/2);
        translate([0,0,thickness+hex_height]) rotate([90,0,0]) scale([1,1,-1]) hexagon(h=hex_height, r=hex_diameter/2);
