module cylindrical_spacer(size, thickness, mounting_hole_count, mounting_hole_size, mounting_hole_spacing) {
    // Calculate the dimensions
    radius = size / 2 - thickness;
    hole_radius = mounting_hole_size / 2;
    hole_center_distance = size / 2 - hole_radius;
    hole_spacing = hole_spacing / 2;

    // Create the cylindrical spacer
    cylinder(size, thickness, center);

    // Create the mounting holes
    // Top hole
    translate([hole_spacing, hole_spacing, 0]) {
        hole(r=hole_radius);
    }
    // Bottom hole
    translate([-hole_spacing, hole_spacing, 0]) {
        hole(r=hole_radius);
    }
    // Left hole
    translate([hole_spacing, -hole_spacing, 0]) {
        hole(r=hole_radius);
    }
    // Right hole
    translate([-hole_spacing, -hole_spacing, 0]) {
        hole(r=hole_radius);
    }
}

