    cylinder(r = size/2, h = size + thickness, center = true);

    // Define the hexagonal recess
    hexagon(x = size/2, y = size/2, sideLength = nutRadius * 0.6, sides = 6);

    // Subtract the hexagonal recess from the cylinder
    difference() {
        cylinder(r = size/2, h = size + thickness, center = true);
        hexagon(x = size/2, y = size/2, sideLength = nutRadius * 0.6, sides = 6);
    }
}

