// Define parameters for the bushing
module flanged_bushing(size, thickness) {
    // Define the base of the bushing
    cylinder(r=size/2, h=size-2*thickness, center=true, chamfer_radius=thickness);

    // Define the flange of the bushing
    cylinder(r=size/2, h=thickness, center=true, chamfer_radius=thickness);

    // Define the mounting holes
    translate([0, size/2, 0]) {
        cylinder(r=2mm, h=size, center=true, chamfer_radius=2mm);
    }
    translate([size/2, 0, 0]) {
        cylinder(r=2mm, h=size, center=true, chamfer_radius=2mm);
    }
    translate([-size/2, 0, 0]) {
        cylinder(r=2mm, h=size, center=true, chamfer_radius=2mm);
    }
    translate([0, -size/2, 0]) {
        cylinder(r=2mm, h=size, center=true, chamfer_radius=2mm);
    }
}

