module flat_mounting_plate(size, thickness) {
  // Define the size and thickness of the mounting plate
  module plate(size) {
    translate([size/2, size/2, 0]) {
      box(size);
    }
  }

  module hole(radius, position) {
    translate(position) {
      cylinder(radius, height=thickness);
    }
  }

  // Create the flat mounting plate
  plate(size);

  // Create the circular mounting holes
  hole(3.0, [-size/4, size/4, thickness/2]);
  hole(3.0, [-size/4, -size/4, thickness/2]);
  hole(3.0, [size/4, size/4, thickness/2 + thickness/2]);
  hole(3.0, [size/4, -size/4, thickness/2 + thickness/2]);
}

