module cylindricalSpacer(size, holeDiameter, holeDepth, outerDiameter) {
    // Create the outer cylinder
    cylinder(r = outerDiameter / 2, h = size / 2, center = true);

    // Create the holes
    for (i = [0:(holeDiameter / 2):holeDiameter / 2]) {
        difference() {
            cylinder(r = outerDiameter / 2 - i, h = size / 2, center = true);
            translate([0, 0, i]) rotate([0, 1, 0]) cylinder(r = holeDiameter / 2, h = holeDepth, center = true);
        }
    }
}

// Call the module with the desired parameters
