// Define the pipe flange parameters
module pipe_flange(size=77, thickness=15) {
    // Create the main body of the pipe flange
    cylinder(r=size/2, h=size, chamfer_h=thickness/2);

    // Create the holes
    // First hole
    translate([size/2-thickness, 0, size/2-thickness]) {
        cylinder(r=5, h=thickness);
    }

    // Second hole
    translate([size/2-thickness, 0, size/2+thickness]) {
        cylinder(r=5, h=thickness);
    }

    // Third hole
    translate([size/2, 0, size/2-thickness]) {
        cylinder(r=5, h=thickness);
    }

    // Fourth hole
    translate([size/2, 0, size/2+thickness]) {
        cylinder(r=5, h=thickness);
    }
}

// Call the pipe_flange module with the given parameters
