module LBracket(
    size = 93,  // mm
    thickness = 13,  // mm
    hole_diameter = 5,  // mm
    hole_spacing = 10  // mm
) {
    // Create the base L bracket frame
    difference() {
        // Base rectangle
        rectangle(size[size-1] - 2 * hole_spacing, size[size-2] - 2 * hole_spacing, thickness);

        // Vertical beams
        translate([0, (size[size-2] - thickness) / 2, -thickness / 2]) rotate([0, 0, 90]) rectangle(size[size-1] - 2 * hole_spacing, hole_spacing, thickness);
        translate([0, (size[size-2] - thickness) / 2, thickness / 2]) rotate([0, 0, 270]) rectangle(size[size-1] - 2 * hole_spacing, hole_spacing, thickness);

        // Horizontal beams
        translate([size[size-1] / 2, 0, -thickness / 2]) rotate([0, 90, 0]) rectangle(hole_spacing, size[size-2] - 2 * hole_spacing, thickness);
        translate([size[size-1] / 2, 0, thickness / 2]) rotate([0, 90, 180]) rectangle(hole_spacing, size[size-2] - 2 * hole_spacing, thickness);
    }

    // Add circular mounting holes
    for (i = [0:3]) {
        translate([hole_spacing * (i % 2), hole_spacing * (i / 2), 0]) rotate([0, i * 90, 0]) sphere(hole_diameter / 2);
    }
}

