        // Bottom part of the corner gusset
        cylinder(r1=0.5, r2=0.5, h=thickness, center=true, $fn=200);
        // Top part of the corner gusset
        cylinder(r1=0.5, r2=0.5, h=thickness, center=true, $fn=200);
        // Bottom hole
        translate([0, 0, thickness / 2]) cylinder(r=0.2, h=thickness - 0.5, center=true, $fn=200);
        // Top hole
        translate([0, 0, thickness / 2]) cylinder(r=0.2, h=thickness - 0.5, center=true, $fn=200);
    }
}

