// Define the parameterized bushing
module flanged_bushing(size, thickness) {
    // Define the main body
    cylinder(r=size/2, h=size, center=true, chamfer=1, chamfer_radius=size/4);

    // Define the flange
    cylinder(r=size/2, h=thickness, center=true, chamfer=1, chamfer_radius=size/4);

    // Subtract the flange from the main body
    difference() {
        cylinder(r=size/2, h=size, center=true, chamfer=1, chamfer_radius=size/4);
        cylinder(r=size/2, h=thickness, center=true, chamfer=1, chamfer_radius=size/4);
    }
}

