  // Base plate
  difference() {
    box(size[0], size[1], thickness);
    translate([0, 0, thickness + size[2] / 2]) {
      cylinder(d=thickness / 2, h=size[2]);
    }
  }

  // Extended mounting tab
  translate([0, 0, thickness + size[2] / 2]) {
    cylinder(d=thickness / 2, h=size[2] / 2);
  }
}

