// Define parameters for the bracket
$fn = 32; // Number of facets for the chamfer
$inc = 2; // Thickness of the chamfer
$height = 74; // Overall height of the bracket
$thickness = 11; // Thickness of the primary outer edges
$gap = 5; // Gap between the primary outer edges and the secondary inner edges

// Main body of the bracket
union() {
    // Primary outer edges
    translate([0, -thickness/2, 0]) rotate([90, 0, 0]) cylinder(r=thickness/2, h=height, $fn=$fn);
    translate([0, thickness/2, 0]) rotate([90, 0, 0]) cylinder(r=thickness/2, h=height, $fn=$fn);

    // Secondary inner edges
    translate([0, -thickness/2+inc, 0]) rotate([90, 0, 0]) cylinder(r=thickness/2, h=height-2*inc, $fn=$fn);
    translate([0, thickness/2+inc, 0]) rotate([90, 0, 0]) cylinder(r=thickness/2, h=height-2*inc, $fn=$fn);
}

module corner_gusset(
    size_x = 86mm,
    size_y = 86mm,
    thickness = 15mm,
    hole_diameter = 5mm
) {
    // Corner gusset
    union() {
        // Top corner
        difference() {
            cylinder(r = 15mm, h = 5mm, center = true);
            translate([0, 0, 5]) {
                cylinder(r = 15mm, h = 15mm, center = true);
            }
        }

        // Bottom corner
        difference() {
            cylinder(r = 15mm, h = 5mm, center = true);
            translate([0, size_y, 5]) {
                cylinder(r = 15mm, h = 15mm, center = true);
            }
        }

        // Left corner
        difference() {
            cylinder(r = 15mm, h = 5mm, center = true);
            translate([5, 0, 5]) {
                cylinder(r = 15mm, h = 15mm, center = true);
            }
        }

        // Right corner
        difference() {
            cylinder(r = 15mm, h = 5mm, center = true);
            translate([size_x - 5, 0, 5]) {
                cylinder(r = 15mm, h = 15mm, center = true);
            }
        }

        // Mounting holes
        translate([0, size_y / 2 - hole_diameter / 2, 5]) {
            cylinder(r = hole_diameter / 2, h = 10mm, center = true);
        }

        translate([size_x / 2 - hole_diameter / 2, 0, 5]) {
            cylinder(r = hole_diameter / 2, h = 10mm, center = true);
        }

        translate([size_x / 2 - hole_diameter / 2, size_y - hole_diameter / 2, 5]) {
            cylinder(r = hole_diameter / 2, h = 10mm, center = true);
        }

        translate([0, size_y / 2 - hole_diameter / 2, size_y - 5]) {
            cylinder(r = hole_diameter / 2, h = 10mm, center = true);
        }
    }
}

