module cylindricalSpacer(radius, height) {
    // Create the base cylinder
    cylinder(h=height, r=radius, $fn=100);

    // Add four circular mounting holes
    translate([radius, 0, radius]) {
        rotate([90, 0, 0]) {
            cylinder(d=height, r=radius/2, $fn=100);
        }
    }

    translate([radius, height, radius]) {
        rotate([90, 0, 0]) {
            cylinder(d=height, r=radius/2, $fn=100);
        }
    }

    translate([-radius, height, radius]) {
        rotate([90, 0, 0]) {
            cylinder(d=height, r=radius/2, $fn=100);
        }
    }

    translate([-radius, height, -radius]) {
        rotate([90, 0, 0]) {
            cylinder(d=height, r=radius/2, $fn=100);
        }
    }
}

