module circular_pipe_flange(
    outer_diameter=97,
    thickness=9,
    flange_height=5,
    flange_width=3
) {
    // Define the main body of the pipe flange
    difference() {
        cylinder(h=outer_diameter/2, r=outer_diameter/2, center=true, chamfer=0.2);
        // Define the top flange section
        cylinder(h=flange_height, r=outer_diameter/2 - thickness/2, center=true, chamfer=0.2);
        // Define the bottom flange section
        cylinder(h=flange_height, r=outer_diameter/2 + thickness/2, center=true, chamfer=0.2);
        // Define the left flange section
        cylinder(h=flange_height, r=outer_diameter/2 - thickness/2, center=true, chamfer=0.2);
        // Define the right flange section
        cylinder(h=flange_height, r=outer_diameter/2 + thickness/2, center=true, chamfer=0.2);
    }

    // Define the holes for the flange
    translate([0, 0, flange_height + thickness / 2]) {
        difference() {
            cylinder(h=flange_width, r=thickness/2, center=true, chamfer=0.2);
            cylinder(h=flange_width, r=outer_diameter/2 - thickness/2, center=true, chamfer=0.2);
            cylinder(h=flange_width, r=outer_diameter/2 + thickness/2, center=true, chamfer=0.2);
            cylinder(h=flange_width, r=thickness/2, center=true, chamfer=0.2);
        }
    }

    translate([flange_width / 2, 0, flange_height + thickness / 2]) {
        difference() {
            cylinder(h=flange_width, r=thickness/2, center=true, chamfer=0.2);
            cylinder(h=flange_width, r=outer_diameter/2 - thickness/2, center=true, chamfer=0.2);
            cylinder(h=flange_width, r=outer_diameter/2 + thickness/2, center=true, chamfer=0.2);
            cylinder(h=flange_width, r=thickness/2, center=true, chamfer=0.2);
        }
    }
}

