  // Create the hexagonal recess
  hexagon(hex_radius, hex_height, hex_depth, center=true);

  // Subtract the hexagonal recess from the shaft collar body
  difference() {
    cylinder(radius=size/2 - thickness/2, height=size + thickness, center=true);
    hexagon(hex_radius, hex_height, hex_depth, center=true);
  }
}

