module structural_l_bracket(
  diameter = 20,  // mm
  thickness = 12,  // mm
  height = 40    // mm
) {

  // Define the main body of the L-bracket
  difference() {
    cube([diameter * 2, height, thickness]);
    translate([thickness, 0, 0]) cube([thickness * 2, height, thickness]);
    translate([-thickness, 0, 0]) cube([thickness * 2, height, thickness]);
    translate([0, 0, thickness]) cube([diameter * 2, height, thickness]);
  }

  // Define the subtracted hole geometries
  translate([thickness / 2, 0, 0]) cylinder(r = diameter / 2 - thickness / 4, h = height, center = true);
  translate([-thickness / 2, 0, 0]) cylinder(r = diameter / 2 - thickness / 4, h = height, center = true);
  translate([0, 0, thickness / 2]) cylinder(r = diameter / 2 - thickness / 4, h = height, center = true);

  // Prevent 3D rendering artifacts by extending the subtracted hole geometries
  translate([thickness / 2, 0, -thickness / 2]) cylinder(r = diameter / 2 - thickness / 4, h = thickness, center = true);
  translate([-thickness / 2, 0, -thickness / 2]) cylinder(r = diameter / 2 - thickness / 4, h = thickness, center = true);
  translate([0, 0, -thickness / 2]) cylinder(r = diameter / 2 - thickness / 4, h = thickness, center = true);
}

// Call the module with specific parameters
structural_l_bracket();

module flat_mounting_plate(size=64, thickness=12) {
    // Create a rectangular box with the specified size and thickness
    box(
        size = [size, size, thickness],
        center = [0, 0, 0]
    );

    // Define the center through-hole
    // Center through-hole is a subtractive operation between the rectangular box and a smaller rectangular hole
    difference() {
        box(
            size = [size-2, size-2, thickness],
            center = [0, 0, 0]
        );

        // Hole dimensions
        hole_radius = 1.5;
        hole_depth = thickness / 2;

        // Create a smaller rectangular hole with the specified radius and depth
        cylinder(
            radius = hole_radius,
            height = hole_depth,
            center = [0, 0, hole_depth / 2]
        );
    }
}

