// Define the dimensions of the L-bracket
module LBracket(size, thickness) {
    // Define the main body of the L-bracket
    difference() {
        // Cut out the base of the L-bracket
        cylinder(r1=10, r2=10, h=size - 2*thickness, center=false, resolution=20);
        // Cut out the sides of the L-bracket
        translate([0, 0, thickness]) rotate([90, 0, 0]) cylinder(r1=10, r2=10, h=size - 2*thickness, center=false, resolution=20);
        translate([size - 2*thickness, 0, 0]) rotate([0, 90, 0]) cylinder(r1=10, r2=10, h=size - 2*thickness, center=false, resolution=20);
        translate([0, size - 2*thickness, 0]) rotate([0, 0, 90]) cylinder(r1=10, r2=10, h=size - 2*thickness, center=false, resolution=20);
    }

    // Define the holes in the L-bracket
    translate([thickness, thickness, thickness]) rotate([0, 0, 0]) cylinder(r=5, h=thickness - 2*thickness, center=false, resolution=20);
    translate([size - 2*thickness - 5, thickness, thickness]) rotate([0, 0, 0]) cylinder(r=5, h=thickness - 2*thickness, center=false, resolution=20);
    translate([thickness, size - 2*thickness - 5, thickness]) rotate([0, 0, 0]) cylinder(r=5, h=thickness - 2*thickness, center=false, resolution=20);
    translate([size - 2*thickness - 5, size - 2*thickness - 5, thickness]) rotate([0, 0, 0]) cylinder(r=5, h=thickness - 2*thickness, center=false, resolution=20);
}

