            translate([0, size/2, thickness/2]) cylinder(h=thickness, r=10, $fn=40);
            translate([0, size/2, -(thickness/2)]) cylinder(h=thickness, r=10, $fn=40);
            translate([-size/2, size/2, thickness/2]) cylinder(h=thickness, r=10, $fn=40);
            translate([size/2, size/2, thickness/2]) cylinder(h=thickness, r=10, $fn=40);
        }
        translate([size/2, size/2, -(thickness/2)]) cylinder(h=thickness, r=5, $fn=40);
    }
    // Central through-hole
    translate([size/2, 0, thickness/2]) cylinder(h=10, r=10, $fn=40);
}

