module flat_mounting_plate(size = [65, 8], hole_diameter = 5, spacing = 20) {
    // Define the overall size of the plate
    translate([size[0]/2, size[1]/2, 0]) {
        // Define the rectangular pattern of holes
        intersection() {
            for (x = [0:size[0]/hole_diameter-1]) {
                for (y = [0:size[1]/hole_diameter-1]) {
                    translate([x * hole_diameter + spacing, y * hole_diameter + spacing, 0]) {
                        cylinder(diameter = hole_diameter, height = size[2], center = true);
                    }
                }
            }
        }

        // Define the overall size of the plate
        translate([-size[0]/2, -size[1]/2, 0]) {
            // Define the rectangular pattern of holes
            intersection() {
                for (x = [0:size[0]/hole_diameter-1]) {
                    for (y = [0:size[1]/hole_diameter-1]) {
                        translate([x * hole_diameter + spacing, y * hole_diameter + spacing, size[2]]) {
                            cylinder(diameter = hole_diameter, height = size[2], center = true);
                        }
                    }
                }
            }
        }
    }
}

