module hexagonal_standoff(length, thickness) {
    // Create the hexagonal body
    difference() {
        // Define the vertices of the hexagon
        translate([0, 0, 0]) cube([length, length, thickness]);
        translate([length / 2, 0, 0]) cube([length / 2, length, thickness]);
        translate([0, length / 2, 0]) cube([length, length / 2, thickness]);
        translate([-length / 2, length / 2, 0]) cube([length, length / 2, thickness]);
        translate([0, -length / 2, 0]) cube([length, length / 2, thickness]);
        translate([length / 2, -length / 2, 0]) cube([length, length / 2, thickness]);
    }
}

