module hexagonal_standoff(
    size = 40,
    thickness = 10,
    nut_size = 10
) {
    // Create the hexagonal standoff
    difference() {
        cube(size, center=true);
        // Create the hexagonal recess
        translate([0, size/2, thickness/2]) {
            translate([0, -size/2, thickness/2]) {
                difference() {
                    cube(size, center=true);
                    rotate([0, 0, 60]) {
                        cube(size, center=true);
                    }
                }
            }
        }
    }

    // Subtract the hexagonal recess
    translate([0, size/2, thickness/2]) {
        translate([0, -size/2, thickness/2]) {
            difference() {
                cube(size, center=true);
                rotate([0, 0, 60]) {
                    cube(size, center=true);
                }
            }
        }
    }
}

