    difference() {
        // First hole
        translate([size/4, size/4, thickness-1])
        cylinder(r1=thickness/2, r2=thickness/2, h=size/2, center=true, chamfer=0.2);

        // Second hole
        translate([-size/4, size/4, thickness-1])
        cylinder(r1=thickness/2, r2=thickness/2, h=size/2, center=true, chamfer=0.2);

        // Third hole
        translate([size/4, -size/4, thickness-1])
        cylinder(r1=thickness/2, r2=thickness/2, h=size/2, center=true, chamfer=0.2);

        // Fourth hole
        translate([-size/4, -size/4, thickness-1])
        cylinder(r1=thickness/2, r2=thickness/2, h=size/2, center=true, chamfer=0.2);
