    // Define the main body of the mounting plate
    difference() {
        translate([0, 0, thickness])
        cube([size, size, size]);
        // Define the holes for mounting screws
        translate([0, 0, thickness - 5])
        cylinder(d=2, h=10);
        translate([size / 2, size / 2, thickness - 5])
        cylinder(d=2, h=10);
        translate([size, 0, thickness - 5])
        cylinder(d=2, h=10);
        translate([0, size, thickness - 5])
        cylinder(d=2, h=10);
    }
    // Subtract the holes from the main body to prevent artifacts
    translate([0, 0, thickness])
    union() {
        difference() {
            translate([0, 0, thickness - 5])
            cylinder(d=2, h=10);
            translate([size / 2, size / 2, thickness - 5])
            cylinder(d=2, h=10);
            translate([size, 0, thickness - 5])
            cylinder(d=2, h=10);
            translate([0, size, thickness - 5])
            cylinder(d=2, h=10);
        }
        translate([0, 0, thickness])
        difference() {
            translate([0, 0, thickness - 5])
            cylinder(d=2, h=10);
            translate([size / 2, size / 2, thickness - 5])
            cylinder(d=2, h=10);
            translate([size, 0, thickness - 5])
            cylinder(d=2, h=10);
            translate([0, size, thickness - 5])
            cylinder(d=2, h=10);
        }
    }
}

