module flat_mounting_plate(size_x=84, size_y=84, thickness=12, chamfer_thickness=2) {
    // Define the primary outer edges with a chamfer
    translate([0, 0, thickness/2]) {
        linear_extrude(thickness) {
            circle(d=size_x/2, $fn=100);
            translate([-chamfer_thickness, 0, 0]) {
                circle(d=size_x/2, $fn=100);
            }
            translate([0, -chamfer_thickness, 0]) {
                circle(d=size_x/2, $fn=100);
            }
            translate([chamfer_thickness, -chamfer_thickness, 0]) {
                circle(d=size_x/2, $fn=100);
            }
        }
    }
    // Define the secondary outer edges with a chamfer
    translate([size_x/2, 0, thickness/2]) {
        linear_extrude(thickness) {
            circle(d=size_y/2, $fn=100);
            translate([-chamfer_thickness, 0, 0]) {
                circle(d=size_y/2, $fn=100);
            }
            translate([0, -chamfer_thickness, 0]) {
                circle(d=size_y/2, $fn=100);
            }
            translate([chamfer_thickness, -chamfer_thickness, 0]) {
                circle(d=size_y/2, $fn=100);
            }
        }
    }
    // Define the tertiary outer edges with a chamfer
    translate([size_x/2, size_y/2, thickness/2]) {
        linear_extrude(thickness) {
            circle(d=size_x/2, $fn=100);
            translate([-chamfer_thickness, 0, 0]) {
                circle(d=size_x/2, $fn=100);
            }
            translate([0, -chamfer_thickness, 0]) {
                circle(d=size_x/2, $fn=100);
            }
            translate([chamfer_thickness, -chamfer_thickness, 0]) {
                circle(d=size_x/2, $fn=100);
            }
        }
    }
}

