module flanged_bushing(radius, thickness, chamfer_size) {
    // Main body
    difference() {
        cylinder(r=radius-thickness, h=thickness*2);
        cylinder(r=radius, h=thickness*2-0.1);
    }

    // Chamfer on primary outer edges
    chamfer(
        radius=radius-thickness,
        height=thickness*2,
        chamfer_size=chamfer_size
    );

    // Inner clearance
    difference() {
        cylinder(r=radius-thickness+0.1, h=thickness*2-0.1);
        cylinder(r=radius-thickness, h=thickness*2);
    }
}

