    cylinder(h=thickness, r=size[0] / 2 - 1, segments=20);

    translate([0, size[1] / 2 - 5, thickness / 2])
    cylinder(h=thickness, r=size[1] / 2 - 1, segments=20);

    translate([0, size[1] / 2 + 5, thickness / 2])
    cylinder(h=thickness, r=size[1] / 2 - 1, segments=20);

