module hex_standoff(size, thickness) {
    // Calculate the radius of the hexagon
    h_radius = size / (2 * sin(pi / 6));

    // Calculate the distance between the centers of the mounting holes
    hole_spacing = h_radius * sqrt(3);

    // Calculate the height of the mounting holes
    hole_height = thickness * (1 - sin(pi / 6));

    // Calculate the distance from the center of the mounting holes to the center of the hexagon
    hole_distance = hole_spacing / 2;

    // Calculate the coordinates of the mounting holes
    hole1_x = 0;
    hole1_y = -hole_height;

    hole2_x = hole_distance;
    hole2_y = -hole_height;

    hole3_x = hole_distance;
    hole3_y = hole_height;

    hole4_x = 0;
    hole4_y = hole_height;

    // Create the mounting holes
    cylinder(hole_height, 0.1, [hole1_x, hole1_y, 0], [hole2_x, hole2_y, 0], [hole3_x, hole3_y, 0], [hole4_x, hole4_y, 0]);

    // Create the hexagonal standoff
    polygon(points=[
        [0, -h_radius],
        [h_radius * sqrt(3), -h_radius],
        [h_radius * sqrt(3), h_radius],
        [0, h_radius],
        [-h_radius * sqrt(3), h_radius],
        [-h_radius * sqrt(3), -h_radius]
    ], holes=[
        [0, -h_radius]
    ]);

    // Subtract the mounting holes from the hexagonal standoff
    difference() {
        union() {
            polygon(points=[
                [0, -h_radius],
                [h_radius * sqrt(3), -h_radius],
                [h_radius * sqrt(3), h_radius],
                [0, h_radius],
                [-h_radius * sqrt(3), h_radius],
                [-h_radius * sqrt(3), -h_radius]
            ], holes=[
                [0, -h_radius]
            ]);

            cylinder(hole_height, 0.1, [hole1_x, hole1_y, 0], [hole2_x, hole2_y, 0], [hole3_x, hole3_y, 0], [hole4_x, hole4_y, 0]);
        }

        cylinder(thickness, 0.1, [0, 0, 0], [0, 0, 0]);
    }
}

