module hexagonal_standoff(
    length = 100, // overall length in mm
    width = 100, // overall width in mm
    height = 12,  // height of the standoff in mm
    hole_diameter = 5  // diameter of the holes in mm
) {
    // Main body
    difference() {
        cube([length, width, height]);

        // Center hole
        translate([0, 0, height - hole_diameter / 2]) {
            cylinder(diameter = hole_diameter, height = hole_diameter);
        }
    }

    // Outer hexagonal hole
    translate([0, 0, height - hole_diameter]) {
        rotate([0, 0, 90]) {
            hexagon(length = hole_diameter, height = height - hole_diameter);
        }
    }

    // Inner hexagonal hole
    translate([0, 0, height - hole_diameter]) {
        rotate([0, 0, 270]) {
            hexagon(length = hole_diameter, height = height - hole_diameter);
        }
    }
}

