module circular_pipe_flange(radius, thickness) {
    // Create the outer circle of the pipe
    union() {
        cylinder(radius + thickness, thickness, center=[0,0,thickness/2], height=radius*2, convexity=5);
        translate([0,0,radius]) rotate([0,90,0]) cylinder(radius + thickness, thickness, center=[0,0,thickness/2], height=radius*2, convexity=5);
    }

    // Create the hexagonal recess
    difference() {
        // Calculate the radius of the hexagon
        hexagon_radius = radius * sqrt(3) / 2;
        // Create the hexagon recess
        union() {
            for (i = [1:6]) {
                translate([hexagon_radius * cos(2 * 3.14159 * i / 6), hexagon_radius * sin(2 * 3.14159 * i / 6), 0]) {
                    cylinder(hexagon_radius, thickness, center=[0,0,thickness/2], height=hexagon_radius * 2, convexity=5);
                }
            }
        }
    }
}

