// Define the dimensions of the L-bracket
module LBracket(size, thickness) {
  // Define the main body of the L-bracket
  difference() {
    translate([0, 0, size / 2]) {
      cylinder(r1 = size / 2 - thickness / 2, r2 = size / 2 + thickness / 2, h = size - thickness);
    }
    translate([0, 0, -size / 2]) {
      cylinder(r1 = size / 2 - thickness / 2, r2 = size / 2 + thickness / 2, h = size - thickness);
    }
    translate([size / 2 - thickness, 0, 0]) {
      cylinder(r1 = thickness, r2 = thickness, h = size);
    }
    translate([-size / 2 + thickness, 0, 0]) {
      cylinder(r1 = thickness, r2 = thickness, h = size);
    }
  }

  // Define the holes in the L-bracket
  translate([0, 0, size / 2]) {
    translate([thickness / 2, thickness / 2, 0]) {
      sphere(r = thickness / 2);
    }
    translate([size / 2 - thickness, thickness / 2, 0]) {
      sphere(r = thickness / 2);
    }
  }
  translate([0, 0, -size / 2]) {
    translate([thickness / 2, thickness / 2, 0]) {
      sphere(r = thickness / 2);
    }
    translate([size / 2 - thickness, thickness / 2, 0]) {
      sphere(r = thickness / 2);
    }
  }
}

