module flanged_bushing(radius, thickness) {
    // Main body
    cylinder(d = radius * 2, h = thickness, center = true, chamfer = radius * 0.1);

    // Flange
    difference() {
        // Base flange
        cylinder(d = radius * 2, h = thickness, center = true, chamfer = radius * 0.1);

        // Top flange
        translate([0, 0, thickness - radius]) {
            cylinder(d = radius * 2, h = thickness, center = true, chamfer = radius * 0.1);
        }

        // Center hole
        translate([0, 0, thickness - radius + 0.1]) {
            cylinder(d = 2 * radius, h = 1, center = true, chamfer = radius * 0.1);
        }
    }
}

