arc($r=$thickness / 2 - $mm, $center=[0, $overall_size - $thickness / 2, $overall_size / 2], $start=[0, $overall_size - $thickness / 2, $overall_size / 2 + $thickness], $end=[0, $overall_size - $thickness / 2, $overall_size / 2 + 2 * $thickness]);

// Join the arcs to form the chamfer
intersection() {
