    translate([chamfer, chamfer, chamfer])
      rotate([90, 90, 0])
        translate([0, 0, thickness - chamfer])
          cylinder(r=chamfer, h=thickness - chamfer, center=true, resolution=10);
    translate([chamfer, chamfer, thickness])
      rotate([90, 0, 90])
        translate([0, 0, thickness - chamfer])
          cylinder(r=chamfer, h=thickness - chamfer, center=true, resolution=10);
    translate([chamfer, thickness, chamfer])
      rotate([0, 90, 90])
        translate([0, 0, thickness - chamfer])
          cylinder(r=chamfer, h=thickness - chamfer, center=true, resolution=10);
    translate([thickness, chamfer, chamfer])
      rotate([90, 0, 0])
        translate([0, 0, thickness - chamfer])
          cylinder(r=chamfer, h=thickness - chamfer, center=true, resolution=10);
  }
}

