            cylinder(r=hex_diameter/2, h=size/2); // Hexagonal recess
        }
        translate([0, 0, size/2]) {
            cylinder(r=hex_diameter/2, h=size/2); // Hexagonal recess
        }
        translate([0, size/2, thickness/2]) {
            cylinder(r=hex_diameter/2, h=size/2); // Hexagonal recess
        }
        translate([size/2, size/2, thickness/2]) {
            cylinder(r=hex_diameter/2, h=size/2); // Hexagonal recess
        }
    }

    // Main L-bracket body
    union() {
        translate([-size/4, -size/4, thickness/2]) {
            cylinder(r=10, h=size*2); // Base
        }
        translate([-size/4, size/4, thickness/2]) {
            cylinder(r=10, h=size*2); // Base
        }
        translate([size/4, -size/4, thickness/2]) {
            cylinder(r=10, h=size*2); // Base
        }
        translate([size/4, size/4, thickness/2]) {
            cylinder(r=10, h=size*2); // Base
        }
    }
}

