module cylinder_spacer(size, thickness, chamfer) {
    // Generate the cylinder
    cylinder(h=size, r=size, center=true);

    // Add a chamfer to the primary outer edges
    difference() {
        // Outer edges of the cylinder
        union() {
            // First outer edge
            linear_extrude(height=chamfer, segments=100) {
                sphere(r=size/2 - chamfer/2);
            }
            // Second outer edge
            linear_extrude(height=chamfer, segments=100) {
                sphere(r=size/2 - chamfer/2);
            }
        }

        // Inner edges of the cylinder (if any)
        difference() {
            // Inner edge
            union() {
                sphere(r=size/2 - chamfer/2);
            }
        }
    }
}

