module hexagonal_standoff(
    base_plate_width = 32,
    base_plate_thickness = 11,
    tab_length = 8,
    tab_width = 3
) {
    // Base plate
    translate([0, 0, base_plate_thickness / 2]) {
        cylinder(r = base_plate_width / 2, h = base_plate_thickness, center = true, resolution = 100);
    }

    // Tab
    translate([0, 0, base_plate_thickness + tab_length / 2]) {
        cylinder(r = tab_width / 2, h = tab_length, center = true, resolution = 100);
    }

    // Combine the base plate and tab using a union
    union() {
        cylinder(r = base_plate_width / 2, h = base_plate_thickness, center = true, resolution = 100);
        cylinder(r = tab_width / 2, h = tab_length, center = true, resolution = 100);
    }
}

