    linear_extrude(height=base_thick) {
      polygon(points=[[base_thick*1.5, -base_thick*1.5], [base_thick*2, -base_thick*1.5], [base_thick*2, -base_thick*2], [base_thick*1.5, -base_thick*2], [base_thick*1.5, -base_thick*1.5]]);
    }
  }

  // Tab
  linear_extrude(height=tab_thick) {
    polygon(points=[[tab_thick*1.5, -tab_thick*1.5], [tab_thick*2, -tab_thick*1.5], [tab_thick*2, -tab_thick*2], [tab_thick*1.5, -tab_thick*2], [tab_thick*1.5, -tab_thick*1.5]]);
  }
}

