    rotate(-45) {
        difference() {
            // Hexagon
            translate([0, size/2, 0]) {
                hexagon(size);
            }
            // Sticks
            translate([0, size/2, thickness/2]) {
                cylinder(r1=size/2, r2=size/4, h=size-thickness);
            }
            translate([0, size/2, -(size-thickness)/2]) {
                cylinder(r1=size/2, r2=size/4, h=size-thickness);
            }
        }
    }

    // Mounting holes
    translate([-size/2, 0, thickness/2]) {
        cylinder(r=0.2, h=size);
    }
    translate([-size/2, 0, -(size-thickness)/2]) {
        cylinder(r=0.2, h=size);
    }
    translate([size/2, 0, thickness/2]) {
        cylinder(r=0.2, h=size);
    }
    translate([size/2, 0, -(size-thickness)/2]) {
        cylinder(r=0.2, h=size);
    }
}

