// Create the hole in the collar
hole = cylinder(r=$radHole, h=$thick, center=true, fn=$fn);

// Subtract the hole from the body
collar = difference(body, hole);

// Render the collar with a small offset to avoid artifacts
collar_render = translate([0, 0, $thick + 0.1]) * collar;

// Display the collar
difference([collar_render, hole]) {
    cylinder(r=radBody, h=100, center=true, fn=$fn);
}

module flat_mounting_plate(size, thickness, chamfer) {
    // Define the overall size of the plate
    translate([0, 0, 0]) {
        difference() {
            // Define the inner plate with the chamfer
            cube([size - 2*chamfer, size - 2*chamfer, thickness - 2*chamfer], center=true);

            // Define the outer plate with the chamfer
            translate([chamfer, chamfer, chamfer]) {
                cube([size - 2*chamfer, size - 2*chamfer, thickness - 2*chamfer], center=true);
            }
        }
    }
}

