module flanged_bushing(radius, thickness, chamfer_radius, flange_depth) {
    // Primary outer edges with chamfer
    cylinder(r=radius+chamfer_radius, h=thickness, center=true, chamfer=true, chamfer_radius=chamfer_radius);

    // Flange
    cylinder(r1=radius, r2=radius+flange_depth, h=thickness, center=true, chamfer=true, chamfer_radius=flange_radius);
}

