module flange_bushing(
    diameter = 30mm,
    thickness = 14mm,
    chamfer = 2mm
) {
    // Define the flange's inner and outer edges
    linear_extrude(height = thickness, center = true) {
        circle(diameter/2);
    }

    // Define the chamfer on the primary outer edges
    linear_extrude(height = thickness, center = true) {
        difference() {
            circle(diameter/2);
            cylinder(diameter = diameter - 2*chamfer, height = thickness, center = true);
        }
    }

    // Create the final bushing by unioning the inner and outer edges
    union() {
        linear_extrude(height = thickness, center = true) {
            circle(diameter/2);
        }
        linear_extrude(height = thickness, center = true) {
            difference() {
                circle(diameter/2);
                cylinder(diameter = diameter - 2*chamfer, height = thickness, center = true);
            }
        }
    }
}

