        cylinder(h=thickness, d=7, $fn=50); // inner cylinder
        difference() {
            translate([0, thickness/2, 0]) {
                cylinder(h=size-10, d=8, $fn=50); // outer cylinder with hole
            }
            translate([0, -thickness/2, 0]) {
                cylinder(h=size-10, d=7, $fn=50); // inner cylinder with hole
            }
        }
    }
}

