// Define the dimensions of the U-channel bracket
module u_channel_bracket(size, thickness, chamfer) {
    // Create the front section of the bracket
    difference() {
        cube([size, thickness, size], center = true); // Front face
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [0, 0, size / 2], end = [0, 0, -thickness / 2]); // Front edge
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [-size / 2, 0, size / 2], end = [-size / 2, 0, -thickness / 2]); // Front edge
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [0, size / 2, size / 2], end = [0, size / 2, -thickness / 2]); // Front edge
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [0, -size / 2, size / 2], end = [0, -size / 2, -thickness / 2]); // Front edge
    }

    // Create the rear section of the bracket
    difference() {
        cube([size, thickness, size], center = true); // Rear face
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [0, 0, size / 2], end = [0, 0, -thickness / 2]); // Rear edge
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [-size / 2, 0, size / 2], end = [-size / 2, 0, -thickness / 2]); // Rear edge
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [0, size / 2, size / 2], end = [0, size / 2, -thickness / 2]); // Rear edge
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [0, -size / 2, size / 2], end = [0, -size / 2, -thickness / 2]); // Rear edge
    }

    // Create the side section of the bracket
    difference() {
        cube([size, thickness, size], center = true); // Side face
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [size / 2, 0, size / 2], end = [size / 2, 0, -thickness / 2]); // Side edge
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [-size / 2, 0, size / 2], end = [-size / 2, 0, -thickness / 2]); // Side edge
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [size / 2, thickness / 2, size / 2], end = [size / 2, thickness / 2, -thickness / 2]); // Side edge
        cylinder(r = size / 2, h = thickness, center = true, chamfer = chamfer, start = [size / 2, -thickness / 2, size / 2], end = [size / 2, -thickness / 2, -thickness / 2]); // Side edge
    }
}

