// Parameterized corner gusset
module corner_gusset(size = 88, thickness = 3, chamfer = 2) {
    // Create the base of the gusset
    translate([0, 0, thickness / 2]) cube([size, size, thickness]);

    // Create the top face of the gusset
    translate([0, 0, thickness + chamfer]) cube([size, size, 2 * chamfer]);

    // Create the bottom face of the gusset
    translate([0, 0, -thickness - chamfer]) cube([size, size, 2 * chamfer]);

    // Create the side faces of the gusset
    difference() {
        translate([thickness / 2, 0, 0]) cube([thickness, size, thickness]);
        translate([0, thickness / 2, 0]) cube([size, thickness, thickness]);
        translate([0, 0, thickness / 2]) cube([thickness, size, thickness]);
    }
}

