module structural_l_bracket(length, thickness, hole_diameter) {
    // Create the bottom part of the bracket
    difference() {
        cube([length, thickness, thickness]);
        translate([0, 0, thickness / 2]) {
            cube([length, thickness / 2, thickness / 2]);
        }
    }

    // Create the top part of the bracket
    translate([0, length, thickness / 2]) {
        cube([length, thickness / 2, thickness / 2]);
