module structuralLBracket(radius, height, diameter, thickness) {
    // Define the size of the bracket
    module bracketBody(radius, height, diameter) {
        difference() {
            cylinder(diameter/2, height, $fn=20);
            translate([radius, height/2, 0]) cylinder(diameter/2, height/2, $fn=20);
        }
    }

    // Define the mounting holes
    module mountingHoles(radius, diameter) {
        difference() {
            sphere(diameter/2);
            translate([0, 0, thickness/2]) sphere(diameter/2);
            translate([0, 0, -thickness/2]) sphere(diameter/2);
            translate([0, height, thickness/2]) sphere(diameter/2);
            translate([0, height, -thickness/2]) sphere(diameter/2);
        }
    }

    // Create the structural L-bracket
    difference() {
        bracketBody(radius, height, diameter);
        mountingHoles(radius, diameter);
    }
}

