module flanged_bushing(size, hole_diameter, hole_distance) {
    // Calculate the dimensions of the flange
    flange_width = size - 2 * hole_diameter;
    flange_height = size - 2 * hole_distance;

    // Calculate the position of the mounting holes
    hole_positions = [
        [flange_width / 4, hole_distance / 2],
        [flange_width / 2, hole_distance / 2],
        [flange_width / 4, size - hole_distance / 2],
        [flange_width / 2, size - hole_distance / 2]
    ];

    // Define the material properties
    material = "steel";

    // Define the hole properties
    hole_material = "copper";

    // Define the flange material
    flange_material = "aluminum";

    // Create the flange
    translate([-(flange_width / 2), -(flange_height / 2), 0]) {
        box([flange_width, flange_height, 10]);
    }

    // Create the mounting holes
    translate(hole_positions) {
        cylinder(hole_diameter, hole_diameter, 10, material=hole_material);
    }

    // Create the flange material
    translate([-(flange_width / 2), -(flange_height / 2), 10]) {
        box([flange_width, flange_height, 10], material=flange_material);
    }
}

