    linear_extrude(z = thickness) {
        cylinder(r = size/2, h = size*2);
    }

    // Hole on the top
    rotate([90, 0, 0]) {
        translate([0, 0, thickness/2]) {
            cylinder(r = size/2, h = thickness);
        }
    }

    // Hole on the bottom
    rotate([90, 0, 0]) {
        translate([0, 0, -thickness/2]) {
            cylinder(r = size/2, h = thickness);
        }
    }

    // Hole on the left
    rotate([0, 90, 0]) {
        translate([-size/2, 0, thickness/2]) {
            cylinder(r = size/2, h = thickness);
        }
    }

    // Hole on the right
    rotate([0, 90, 0]) {
        translate([size/2, 0, thickness/2]) {
            cylinder(r = size/2, h = thickness);
        }
    }
}

