    hole_diameter = 6
) {
    // Main body
    difference() {
        cube([length, width, depth]);

        // First hole in the body
        translate([length/2 - hole_diameter/2, width/2 - hole_diameter/2, depth/2 - hole_diameter/2]) {
            cylinder(r=hole_diameter/2, h=depth, center=true);
        }

        // Second hole in the body
        translate([length/2 - hole_diameter/2, width/2 + hole_diameter/2, depth/2 - hole_diameter/2]) {
            cylinder(r=hole_diameter/2, h=depth, center=true);
        }

        // Third hole in the body
        translate([length/2 - hole_diameter/2, width/2 - hole_diameter/2, depth/2 + hole_diameter/2]) {
            cylinder(r=hole_diameter/2, h=depth, center=true);
        }

        // Fourth hole in the body
        translate([length/2 - hole_diameter/2, width/2 + hole_diameter/2, depth/2 + hole_diameter/2]) {
            cylinder(r=hole_diameter/2, h=depth, center=true);
        }
    }
}

