module pipe_flange(r, t, h) {
    // Calculate the height of the flange above the center hole
    h_center = h - t;

    // Create the flange body
    cylinder(radius=r, height=h, center=false);

    // Create the central through-hole
    difference() {
        cylinder(radius=r, height=t, center=false);
        cylinder(radius=r, height=h_center, center=false);
    }
}

