module shaft_collar(size = 54, thickness = 13) {
    // Define the inner and outer radius of the shaft collar
    outer_radius = size / 2;
    inner_radius = outer_radius - thickness / 2;

    // Define the depth of the hole
    hole_depth = thickness / 2;

    // Define the height of the collar
    collar_height = outer_radius + hole_depth;

    // Define the cylinder for the outer surface
    cylinder(outer_radius, collar_height, centered=true);

    // Define the cylinder for the inner surface
    cylinder(inner_radius, hole_depth, centered=true);

    // Define the hole using a difference operation
    difference() {
        cylinder(outer_radius, collar_height, centered=true);
        cylinder(inner_radius, hole_depth, centered=true);
    }
}

