        cylinder(r = hole_radius, h = hole_depth, center = true);
    }

    translate([-width / 2, hole_radius, thickness / 2]) {
        cylinder(r = hole_radius, h = hole_depth, center = true);
    }

    translate([0, height / 2, thickness / 2]) {
        cylinder(r = hole_radius, h = hole_depth, center = true);
    }

    translate([0, -height / 2, thickness / 2]) {
        cylinder(r = hole_radius, h = hole_depth, center = true);
    }

    // Create the holes on the top face
    translate([width / 2, -hole_radius, thickness / 2]) {
        cylinder(r = hole_radius, h = hole_depth, center = true);
    }

    translate([-width / 2, -hole_radius, thickness / 2]) {
        cylinder(r = hole_radius, h = hole_depth, center = true);
    }
}

