// Define the main body of the bushing
module flanged_bushing(radius, thickness) {
    // Bottom half of the bushing
    union() {
        // Bottom face
        rotate([90, 0, 0]) {
            sphere(r=radius, d=thickness);
        }
        // Bottom cap
        rotate([0, 0, 180]) {
            cylinder(r1=radius, r2=radius, h=thickness);
        }
        // Top cap
        rotate([0, 0, 180]) {
            cylinder(r1=radius, r2=radius, h=thickness);
        }
        // Top face
        rotate([90, 0, 0]) {
            sphere(r=radius, d=thickness);
        }
    }

    // Mounting holes
    difference() {
        // Outer circle
        circle(r=radius+1);
        // Inner circle
        circle(r=radius-1);
        // Center hole
        translate([0, 0, thickness/2]) {
            cylinder(r=radius-2, h=thickness);
        }
    }
}

