module circular_pipe_flange(r, t) {
  // Main body
  difference() {
    sphere(r + 2 * t);
    sphere(r - 2 * t);
  }

  // Holes
  difference() {
    translate([0, 0, t + 2]) cylinder(r, 10, 100);
    translate([0, 0, 2 - t - 2]) cylinder(r, 10, 100);
  }

  // Outer surface
  union() {
    translate([0, 0, t + 2]) cylinder(r, 10, 100);
    translate([0, 0, 2 - t - 2]) cylinder(r, 10, 100);
  }
}

