    translate([0, 0, thickness / 2]) {
        rotate([90, 0, 0]) {
            cylinder(r=radius + thickness / 2, h=thickness);
        }
    }

    // Combine base plate and tab using union
    union() {
        cylinder(r=radius + thickness / 2, h=thickness);
        rotate([90, 0, 0]) {
            cylinder(r=radius + thickness / 2, h=thickness);
