module u_channel_bracket(size, thickness, chamfer) {
    // Create the primary outer edges
    difference() {
        translate([0, 0, thickness / 2]) {
            cylinder(r=thickness / 2, h=size - 2 * thickness, center=1);
        }
        translate([size - thickness, 0, thickness / 2]) {
            cylinder(r=thickness / 2, h=size - 2 * thickness, center=1);
        }
        translate([0, size - thickness, thickness / 2]) {
            cylinder(r=thickness / 2, h=size - 2 * thickness, center=1);
        }
        translate([size - thickness, size - thickness, thickness / 2]) {
            cylinder(r=thickness / 2, h=size - 2 * thickness, center=1);
        }
    }

    // Create the primary inner edges
    difference() {
        translate([0, 0, thickness / 2]) {
            cylinder(r=(thickness / 2) - chamfer, h=size - 2 * thickness, center=1);
        }
        translate([size - thickness, 0, thickness / 2]) {
            cylinder(r=(thickness / 2) - chamfer, h=size - 2 * thickness, center=1);
        }
        translate([0, size - thickness, thickness / 2]) {
            cylinder(r=(thickness / 2) - chamfer, h=size - 2 * thickness, center=1);
        }
        translate([size - thickness, size - thickness, thickness / 2]) {
            cylinder(r=(thickness / 2) - chamfer, h=size - 2 * thickness, center=1);
        }
    }
}

