    // Top hole with rounded corners
    translate([0, size-3*thickness, 0]) {
        cylinder(r=holeR, h=thickness, center=true, chamfer=0.1);
        rotateX(45) {
            rotateY(45) {
                translate([-holeR/2, -holeR/2, -thickness]) {
                    sphere(r=holeR/2, h=2*thickness);
                }
            }
        }
