module cylinder_spacer(size, thickness) {
  // Define the center of the spacer
  center = [size/2, size/2, thickness/2];
  // Define the dimensions of the spacer
  height = size - 2 * thickness;
  // Define the radius of the mounting holes
  hole_radius = 3mm;
  // Define the spacing between the mounting holes
  hole_spacing = 5mm;
  // Define the number of mounting holes in each direction
  num_holes = 4;

  // Create the cylindrical spacer
  cylinder(
    center = center,
    radius = size/2 - thickness/2,
    height = height,
    segments = 20
  );

  // Add the mounting holes
  for (x = [0: (num_holes-1): (num_holes-1)]) {
    for (y = [0: (num_holes-1): (num_holes-1)]) {
      translate([x*hole_spacing, y*hole_spacing, thickness/2 + hole_radius])
      cylinder(
        center = [hole_radius, hole_radius, 0],
        radius = hole_radius,
        height = 2 * hole_radius
      );
    }
  }
}

