module corner_gusset(
  size = 68, // in mm
  thickness = 12 // in mm
) {
  // Define the corner gusset body
  cylinder(
    r1 = size / 2, // Radius of the top face
    r2 = size / 2, // Radius of the bottom face
    h = size - thickness, // Height of the body
    center = true, // Center the body on the Z-axis
    chamfer = 2 // Chamfer radius to prevent 3D rendering artifacts
  );

  // Define the subtracted hole
  difference() {
    // Subtract the hole on the top face
    cylinder(
      r1 = size / 4, // Radius of the hole
      r2 = size / 4, // Radius of the hole
      h = size - thickness, // Height of the hole
      center = true, // Center the hole on the Z-axis
      chamfer = 2 // Chamfer radius to prevent 3D rendering artifacts
    );

    // Subtract the hole on the bottom face
    cylinder(
      r1 = size / 4, // Radius of the hole
      r2 = size / 4, // Radius of the hole
      h = size - thickness, // Height of the hole
      center = true, // Center the hole on the Z-axis
      chamfer = 2 // Chamfer radius to prevent 3D rendering artifacts
    );
  }
}

