module structural_l_bracket(
  height = 90, // mm
  thickness = 15 // mm
) {
  // Main body of the L-bracket
  difference() {
    cube([height, height, thickness], center = true);

    // Create the top and bottom halves of the bracket
    difference() {
      cube([height, thickness, thickness], center = true);
      translate([0, height - thickness, 0]) {
        rotate([90, 0, 0]) {
          cube([height, thickness, thickness], center = true);
        }
      }
      translate([0, -height + thickness, 0]) {
        rotate([90, 0, 0]) {
          cube([height, thickness, thickness], center = true);
        }
      }
    }

    // Create the front and back halves of the bracket
    difference() {
      cube([height, thickness, thickness], center = true);
      translate([0, 0, thickness]) {
        rotate([0, 90, 0]) {
          cube([height, thickness, thickness], center = true);
        }
      }
      translate([0, 0, -thickness]) {
        rotate([0, 90, 0]) {
          cube([height, thickness, thickness], center = true);
        }
      }
    }

    // Create the left and right halves of the bracket
    difference() {
      cube([height, thickness, thickness], center = true);
      translate([thickness, 0, 0]) {
        rotate([180, 0, 0]) {
          cube([height, thickness, thickness], center = true);
        }
      }
      translate([-thickness, 0, 0]) {
        rotate([180, 0, 0]) {
          cube([height, thickness, thickness], center = true);
        }
      }
    }

    // Add holes to prevent 3D rendering artifacts
    translate([0, 0, thickness / 2]) {
      difference() {
        cube([thickness, thickness, thickness], center = true);
        translate([0, 0, thickness / 2]) {
          cube([thickness, thickness / 2, thickness], center = true);
        }
      }
    }

    translate([0, 0, -thickness / 2]) {
      difference() {
        cube([thickness, thickness, thickness], center = true);
        translate([0, 0, -thickness / 2]) {
          cube([thickness, thickness / 2, thickness], center = true);
        }
      }
    }
  }
}

structural_l_bracket();

