module hex_recess(size, depth, hex_radius, hex_angle) {
    // Calculate the dimensions of the hexagonal recess
    hex_height = hex_radius * sin(hex_angle);
    hex_width = 2 * hex_radius * cos(hex_angle);

    // Create the hexagonal recess using the `difference` operation
    difference() {
        // Hexagonal recess
        linear_extrude(depth) {
            polygon([hex_radius, hex_width, 0, hex_width, hex_radius, 0, -hex_radius, -hex_width, 0, -hex_width, -hex_radius, 0]);
        }

        // Hexagonal recess with a slight depression to capture the metric hex nut
        linear_extrude(depth + 1) {
            polygon([hex_radius, hex_width, 1, hex_width, hex_radius, 1, -hex_radius, -hex_width, 1, -hex_width, -hex_radius, 1]);
        }
    }
}

