        cylinder(r = size/2 - thickness/2, h = 10, center = true, chamfer = chamfer);
    }

    // Top edge
    intersection() {
        translate([0, thickness/2 - thickness/4, -1]) {
            cylinder(r = size/2 - thickness/2, h = thickness/4, center = true, chamfer = chamfer);
        }
    }

    // Bottom edge
    intersection() {
        translate([0, -thickness/2 + thickness/4, -1]) {
            cylinder(r = size/2 - thickness/2, h = thickness/4, center = true, chamfer = chamfer);
        }
    }
}

