module flanged_bushing(radius=40, thickness=7, chamfer_height=2) {
    // Define the outer cylindrical part
    cylinder(r=radius+thickness, h=thickness, chamfer=chamfer_height);

    // Define the inner cylindrical part
    cylinder(r=radius, h=thickness, chamfer=chamfer_height);

    // Define the flange
    difference() {
        union() {
            // Outer cylindrical part
            cylinder(r=radius+thickness, h=thickness, chamfer=chamfer_height);

            // Inner cylindrical part
            cylinder(r=radius, h=thickness, chamfer=chamfer_height);
        }
        // Difference with the inner cylindrical part
        difference() {
            union() {
                // Outer cylindrical part
                cylinder(r=radius+thickness, h=thickness, chamfer=chamfer_height);

                // Inner cylindrical part
                cylinder(r=radius, h=thickness, chamfer=chamfer_height);
            }
            difference() {
                union() {
                    // Outer cylindrical part
                    cylinder(r=radius+thickness, h=thickness, chamfer=chamfer_height);

                    // Inner cylindrical part
                    cylinder(r=radius, h=thickness, chamfer=chamfer_height);
                }
            }
        }
    }
}

