      // Bottom and top parts of the gusset
      cube([size, size, thickness]);
      // Side parts of the gusset
      translate([-thickness/2, 0, 0]) rotate([-90, 0, 0]) {
        difference() {
          cube([size, thickness, size]);
          translate([0, -thickness/2, 0]) rotate([-90, 0, 0]) {
            cube([thickness, size, size]);
          }
        }
      }
    }
  }
}

