module hexagonal_standoff(size, thickness) {
    // Calculate the side length of the hexagon
    side_length = size / (2 * sin(pi / 6));

    // Calculate the height of the hexagon
    height = side_length * sin(pi / 6);

    // Define the vertices of the hexagon
    vertices = [
        [side_length, 0, 0],
        [side_length, height, 0],
        [-side_length, height, 0],
        [-side_length, 0, 0],
        [0, height / 2, 0],
        [0, -height / 2, 0]
    ];

    // Define the faces of the hexagon
    faces = [
        [0, 1, 2, 3],
        [0, 4, 5, 1],
        [1, 2, 5, 6],
        [2, 3, 6, 7],
        [3, 4, 7, 0],
        [4, 5, 0, 1]
    ];

    // Create the hexagon as a polyhedron
    polyhedron(
        vertices,
        faces,
        chamfer = [0.5, 0.5, 0.5],
        size = [size, size, thickness],
        center = [0, 0, thickness / 2]
    );
}

