            cylinder(diameter = 2 * thickness, height = size + thickness);
        }
    }

    // Hole in the body
    translate([0, 0, size / 2 + thickness]) {
        cylinder(diameter = 1.5 * thickness, height = size / 2);
    }

    // Flange
    translate([0, 0, size + 2 * thickness]) {
        cylinder(diameter = 1.5 * thickness, height = size / 2);
    }

    // Subtracted hole from the body
    translate([0, 0, size + 2 * thickness + thickness / 2]) {
        cylinder(diameter = 1.5 * thickness, height = size / 2);
    }

    // Subtracted hole from the body
    translate([0, 0, size + 2 * thickness + 2 * thickness / 2]) {
        cylinder(diameter = 1.5 * thickness, height = size / 2);
    }
}

