// Parameterized OpenSCAD code for a flanged bushing
module flangedBushing(
    outerRadius = 67/2,
    innerRadius = 67/2 - 0.5,
    thickness = 5
) {
    // Create the outer flange
    union() {
        // Outer cylinder
        cylinder(r=outerRadius, h=thickness, center=true, endstop=outerRadius, chamfer="center", chamferRadius=0.5, chamferAngle=90);

        // Bottom flange
        cylinder(r=outerRadius, h=0.5, center=true, endstop=outerRadius, chamfer="center", chamferRadius=0.5, chamferAngle=90);
    }

    // Create the inner flange
    union() {
        // Inner cylinder
        cylinder(r=innerRadius, h=thickness, center=true, endstop=innerRadius, chamfer="center", chamferRadius=0.5, chamferAngle=90);

        // Top flange
        cylinder(r=innerRadius, h=0.5, center=true, endstop=innerRadius, chamfer="center", chamferRadius=0.5, chamferAngle=90);
    }

    // Create the body
    difference() {
        // Body
        cylinder(r=outerRadius, h=outerRadius + thickness + 0.5, center=true, endstop=outerRadius, chamfer="center", chamferRadius=0.5, chamferAngle=90);

        // Inner body
        cylinder(r=innerRadius, h=innerRadius + thickness + 0.5, center=true, endstop=innerRadius, chamfer="center", chamferRadius=0.5, chamferAngle=90);
    }

    // Create the holes
    difference() {
        // Outer holes
        cylinder(r=outerRadius - 0.5, h=outerRadius, center=true, endstop=outerRadius - 0.5, chamfer="center", chamferRadius=0.5, chamferAngle=90);

        // Inner holes
        cylinder(r=innerRadius - 0.5, h=innerRadius, center=true, endstop=innerRadius - 0.5, chamfer="center", chamferRadius=0.5, chamferAngle=90);
    }
}

