        // Bottom face
        difference() {
            translate([0, -size/2, -size/2]) {
                cube([size, thickness, thickness]);
            }
            translate([0, size/2, -size/2]) {
                cube([size, thickness, thickness]);
            }
            translate([size/2, 0, -size/2]) {
                cube([thickness, size, thickness]);
            }
            translate([-size/2, 0, -size/2]) {
                cube([thickness, size, thickness]);
            }
            translate([0, 0, -size/2]) {
                cube([size, thickness, size]);
            }
            translate([0, 0, size/2]) {
                cube([size, thickness, size]);
            }
        }
        // Hexagonal recess
        difference() {
            hexagon(0.35*size, 0.5*size);
            translate([0, 0, thickness]) {
                difference() {
                    translate([0.35*size, 0.35*size, 0]) {
                        sphere(radius=0.15*size);
                    }
                    translate([-0.35*size, -0.35*size, 0]) {
                        sphere(radius=0.15*size);
                    }
                }
            }
        }
    }
}

// Call the function with specified parameters
l_bracket(65, 12);

