module corner_gusset(size, thickness, hole_diameter) {
    // Define the corner gusset geometry
    difference() {
        // Outer rectangle
        rect(size[0], size[1], size[2]);

        // Inner rectangle for the corner
        rect(size[0] - thickness, size[1] - thickness, size[2] - thickness);

        // Central through-hole
        cylinder(diameter=hole_diameter, height=thickness, center=true);
    }
}

