module base_project(
  size = [77, 77],  // [length, width] in mm
  thickness = 8     // thickness in mm
) {
  // Base body
  translate([-size[0]/2, -size[1]/2, thickness/2]) {
    cylinder(r=20, h=2*thickness+4, center=true);
    cylinder(r=15, h=2*thickness, center=true);
    cylinder(r=10, h=2*thickness, center=true);
    cylinder(r=5, h=2*thickness, center=true);
  }

  // Mounting holes
  translate([-size[0]/4, -size[1]/4, thickness/2 + 5]) {
    sphere(r=3, center=true);
  }
  translate([size[0]/4, -size[1]/4, thickness/2 + 5]) {
    sphere(r=3, center=true);
  }
  translate([-size[0]/4, size[1]/4, thickness/2 + 5]) {
    sphere(r=3, center=true);
  }
  translate([size[0]/4, size[1]/4, thickness/2 + 5]) {
    sphere(r=3, center=true);
  }
}

