    difference() {
        cylinder(r=radius - thickness/2, h=98 - thickness, center=true, chamfer=2);
        // Create a hole in the center of the bushing
        translate([radius - thickness/4, radius - thickness/4, radius - thickness/4]) cylinder(r=thickness/2, h=98 - thickness, center=true, chamfer=2);
    }
}

