module cylinder_spacer(base_diameter, base_height, tab_diameter, tab_height) {
    // Base plate
    difference() {
        cylinder(base_diameter, base_height, h=100);
        cylinder(base_diameter, 100, h=10);
    }

    // Extended tab
    difference() {
        cylinder(tab_diameter, tab_height, h=50);
        cylinder(tab_diameter, 50, h=10);
    }

    // Union both parts
    union() {
        difference() {
            cylinder(base_diameter, base_height, h=100);
            cylinder(base_diameter, 100, h=10);
        }
        difference() {
            cylinder(tab_diameter, tab_height, h=50);
            cylinder(tab_diameter, 50, h=10);
        }
    }
}

// Call the module with parameters
cylinder_spacer(55mm, 12mm, 5mm, 2mm);

module pipe_flange(radius, thickness, num_holes, hole_radius, hole_spacing) {
  // Define the overall size of the pipe flange
  translate([0, 0, -thickness/2])
    difference() {
      // Create the pipe flange body
      cylinder(h=radius, d=2*radius, center=true);
      translate([0, 0, thickness/2])
        cylinder(h=radius, d=2*radius, center=true);
    };

  // Calculate the position of each hole
  for (i = [0: num_holes-1]) {
    x = hole_spacing * (i % num_holes);
    y = hole_spacing * (i / num_holes);
    translate([x, y, 0])
      cylinder(h=hole_radius, d=2*hole_radius, center=true);
  }
}

// Parameters for the pipe flange
radius = 56; // Overall radius in mm
thickness = 15; // Pipe flange thickness in mm
num_holes = 4; // Number of mounting holes
hole_radius = 3; // Radius of each mounting hole in mm
hole_spacing = 8; // Spacing between each mounting hole in mm

pipe_flange(radius, thickness, num_holes, hole_radius, hole_spacing);

// Define the overall size and thickness of the bushing
module flanged_bushing(radius=12.5, thickness=10, spacing=2.5) {
    // Start with a cylinder for the main body
    cylinder(r=radius, h=thickness, center=true);

    // Add four circular mounting holes in a rectangular pattern
    translate([spacing*2, thickness/2, spacing*2]) rotate([90, 0, 0]) cylinder(r=radius/2, h=spacing, center=true);
    translate([spacing, thickness/2, spacing]) rotate([90, 0, 0]) cylinder(r=radius/2, h=spacing, center=true);
    translate([spacing*2, thickness/2, -spacing*2]) rotate([90, 0, 0]) cylinder(r=radius/2, h=spacing, center=true);
    translate([spacing, thickness/2, -spacing*2]) rotate([90, 0, 0]) cylinder(r=radius/2, h=spacing, center=true);
}

// Call the module with the specified parameters
flanged_bushing(radius=12.5, thickness=10, spacing=2.5);

// Parameterized Corner Gusset for OpenSCAD
// Overall size: 66mm x 35mm x 7mm
// Thickness: 7mm
// Holes extend past the main body on the Z-axis to prevent 3D rendering artifacts

module corner_gusset(size, thickness, hole_diameter) {
    // Main body
    difference() {
        cube([size[0], size[1], size[2]]);
        translate([0, 0, thickness/2]) {
            cylinder(r=thickness/2, h=size[2], $fn=100);
        }
    }

    // Holes
    translate([0, 0, thickness/2 + hole_diameter/2]) {
        cylinder(r=hole_diameter/2, h=size[2], $fn=100);
    }
    translate([size[0], 0, thickness/2 + hole_diameter/2]) {
        cylinder(r=hole_diameter/2, h=size[2], $fn=100);
    }
    translate([0, size[1], thickness/2 + hole_diameter/2]) {
        cylinder(r=hole_diameter/2, h=size[2], $fn=100);
    }
    translate([size[0], size[1], thickness/2 + hole_diameter/2]) {
        cylinder(r=hole_diameter/2, h=size[2], $fn=100);
    }
}

// Example usage
corner_gusset([66, 35, 7], 7, 4);

module u_channelBracket(size, thickness, chamferHeight) {
    // Create the primary outer edges of the U-channel
    difference() {
        cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        translate([chamferHeight, 0, 0]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
        translate([0, chamferHeight, 0]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
        translate([0, 0, chamferHeight]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
    }
    // Create the secondary inner edges of the U-channel
    difference() {
        cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        translate([chamferHeight, 0, 0]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
        translate([0, chamferHeight, 0]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
        translate([0, 0, chamferHeight]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
    }
    // Create the primary inner edges of the U-channel
    difference() {
        cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        translate([chamferHeight, 0, 0]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
        translate([0, chamferHeight, 0]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
        translate([0, 0, chamferHeight]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
    }
    // Create the secondary inner edges of the U-channel
    difference() {
        cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        translate([chamferHeight, 0, 0]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
        translate([0, chamferHeight, 0]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
        translate([0, 0, chamferHeight]) {
            cylinder(h = size - 2 * chamferHeight, r1 = thickness / 2, r2 = thickness / 2, center = true);
        }
    }
}

