module shaft_collar(
    outer_diameter = 23,
    hole_diameter = 6,
    hole_distance = 12
) {
    // Calculate the inner diameter of the collar
    inner_diameter = outer_diameter - 2 * hole_diameter;

    // Create the outer cylinder
    cylinder(
        r = outer_diameter / 2,
        h = 100,
        fn = 36,
        center = true
    );

    // Create the inner cylinder
    cylinder(
        r = inner_diameter / 2,
        h = 100,
        fn = 36,
        center = true
    );

    // Add the mounting holes
    for (i = [0:3:3]) {
        for (j = [0:3:3]) {
            translate([i * hole_distance, j * hole_distance, 100]) {
                sphere(
                    r = hole_diameter / 2,
                    center = true
                );
            }
        }
    }
}

