module pipe_flange(radius, thickness) {
  // Main body
  translate([0, 0, thickness / 2]) {
    cylinder(r = radius, h = 93 - thickness);
  }

  // Hole 1
  translate([0, 0, thickness / 2 + 1]) {
    difference() {
      cylinder(r = radius, h = 93 - thickness - 2);
      box([radius - 1, radius - 1, 0]);
    }
  }

  // Hole 2
  translate([0, radius / 2, thickness / 2 + 1]) {
    difference() {
      cylinder(r = radius, h = 93 - thickness - 2);
      box([radius - 1, radius - 1, 0]);
    }
  }

  // Hole 3
  translate([-radius / 2, 0, thickness / 2 + 1]) {
    difference() {
      cylinder(r = radius, h = 93 - thickness - 2);
      box([radius - 1, radius - 1, 0]);
    }
  }

  // Hole 4
  translate([radius / 2, -radius / 2, thickness / 2 + 1]) {
    difference() {
      cylinder(r = radius, h = 93 - thickness - 2);
      box([radius - 1, radius - 1, 0]);
    }
  }
}

pipe_flange(40, 6);

module cylinderSpacer(
    size = 20,
    thickness = 11
) {
