    difference() {
        translate([0, 0, size / 2 + thickness / 2]) {
            cylinder(r=5, h=size + thickness);
        }
        translate([0, 0, size / 2 - thickness / 2]) {
            cylinder(r=5, h=size + thickness);
        }
    }

    // Thinner extended mounting tab
    translate([0, 0, size / 2]) {
        cylinder(r=1, h=size - 2 * thickness);
    }
}

