module LBracket(
    overallSize = 39,
    holeDiameter = 3,
    holeSpacing = 18,
    holeRadius = holeDiameter / 2
) {
    // Create the rectangular part of the bracket
    rectangularPrism(
        width = overallSize,
        height = 9,
        depth = 9,
        center = [0, 0, 0]
    );

    // Create the circular mounting holes
    translate([overallSize / 2 - holeSpacing / 2, overallSize / 2 - holeSpacing / 2, 9]) {
        cylinder(
            radius = holeRadius,
            height = 9,
            center = [0, 0, 0]
        );
    }

    translate([overallSize / 2 + holeSpacing / 2, overallSize / 2 - holeSpacing / 2, 9]) {
        cylinder(
            radius = holeRadius,
            height = 9,
            center = [0, 0, 0]
        );
    }

    translate([overallSize / 2 - holeSpacing / 2, overallSize / 2 + holeSpacing / 2, 9]) {
        cylinder(
            radius = holeRadius,
            height = 9,
            center = [0, 0, 0]
        );
    }

    translate([overallSize / 2 + holeSpacing / 2, overallSize / 2 + holeSpacing / 2, 9]) {
        cylinder(
            radius = holeRadius,
            height = 9,
            center = [0, 0, 0]
        );
    }
}

