module flanged_bushing(size, thickness) {
    // Define the central through-hole
    difference() {
        cylinder(d=size/2, h=thickness, center=true, endcap=true);
        cylinder(d=size/2-0.01, h=thickness-0.01, center=true, endcap=true);
    }

    // Define the outer flange
    cylinder(d=size/2+0.01, h=thickness, center=true, endcap=true);

    // Define the inner flange
    cylinder(d=size/2-0.01, h=thickness, center=true, endcap=true);
}

