module flanged_bushing(size, thickness) {
    // Main body
    translate([0, 0, size - thickness])
    cylinder(diameter=size/2, height=size, center=true);

    // Flange
    translate([0, 0, thickness])
    cylinder(diameter=size/2 - 2*thickness/2, height=thickness, center=true);

    // Holes
    translate([0, 0, 0])
    cylinder(diameter=thickness/2, height=size/2, center=true);

    translate([0, 0, size])
    cylinder(diameter=thickness/2, height=size/2, center=true);
}

