// Define the project enclosure base parameters
module project_enclosure_base(params = [66mm, 6mm, 6mm]) {
    // Create the main body of the base
    cube([params[0], params[1], params[2]]);

    // Create holes for the base
    difference() {
        // Create a smaller cube for the base
        cube([params[0] - 12mm, params[1] - 12mm, params[2] - 12mm]);

        // Create a larger cube for the base
        cube([params[0], params[1], params[2]]);
    }

    // Extend the holes past the main body on the Z-axis
    translate([0, 0, params[2]]) {
        difference() {
            // Create a smaller cube for the base
            cube([params[0] - 12mm, params[1] - 12mm, params[2] - 12mm]);

            // Create a larger cube for the base
            cube([params[0], params[1], params[2]]);
        }
    }
}

// Call the project enclosure base function with the desired size
project_enclosure_base();

